#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 23681 - Bachet's Game
 * 
 * 解題思路：
 * 1. 這是一個典型的博弈問題，可以使用動態規劃 (DP) 解決。
 * 2. 令 win[i] 表示當桌上有 i 顆石頭時，當前玩家是否必勝。
 * 3. 狀態轉移：
 *    - 如果存在一種移動方式，使得拿走 s 顆石頭後剩餘的石頭數 i-s 處於必敗態 (win[i-s] == false)。
 *    - 則當前狀態為必勝態 (win[i] = true)。
 *    - 否則，若所有移動方式都會導致對手進入必勝態，則當前狀態為必敗態。
 * 4. 初始狀態：win[0] = false (拿走最後一顆石頭的人贏，所以剩下 0 顆時輪到的人輸)。
 */

bool win_table[1000001];

int main() {
    int n, m;
    while (cin >> n >> m) {
        vector<int> moves(m);
        for (int i = 0; i < m; i++) cin >> moves[i];

        win_table[0] = false;
        for (int i = 1; i <= n; i++) {
            win_table[i] = false;
            for (int s : moves) {
                if (i >= s && !win_table[i - s]) {
                    win_table[i] = true;
                    break;
                }
            }
        }

        if (win_table[n]) cout << "Stan wins" << endl;
        else cout << "Ollie wins" << endl;
    }
    return 0;
}
